<?php
namespace App\Http\Controllers;
use App\Models\{Listing,PaymentEvent,Transaction}; use App\Services\PaystackService; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str;
class PaymentController extends Controller {
 public function initialize(Request $r,Listing $listing,PaystackService $paystack){abort_if($listing->user_id===$r->user()->id,422,'You cannot purchase your own listing.');abort_unless($listing->status==='active',409);$tx=Transaction::create(['listing_id'=>$listing->id,'buyer_id'=>$r->user()->id,'seller_id'=>$listing->user_id,'amount'=>$listing->price,'status'=>'pending_payment','paystack_reference'=>'DM-'.Str::upper(Str::random(18))]);$data=$paystack->initialize($r->user()->email,(int)round(((float)$listing->price)*100),$tx->paystack_reference,route('payments.callback',['reference'=>$tx->paystack_reference]));return redirect()->away($data['authorization_url']);}
 public function callback(Request $r,PaystackService $paystack){$ref=$r->string('reference')->value();$tx=Transaction::where('paystack_reference',$ref)->firstOrFail();$data=$paystack->verify($ref);if(($data['status']??null)!=='success'||(int)($data['amount']??0)!==(int)round(((float)$tx->amount)*100))abort(422,'Payment could not be verified.');DB::transaction(function()use($tx){$locked=Transaction::lockForUpdate()->find($tx->id);if($locked->status==='pending_payment'){$locked->update(['status'=>'paid_held','paid_at'=>now()]);$locked->listing()->update(['status'=>'sold']);}});return redirect()->route('dashboard')->with('success','Payment verified and marked as protected.');}
 public function webhook(Request $r,PaystackService $paystack){$raw=$r->getContent();if(!$paystack->validWebhook($raw,$r->header('x-paystack-signature')))abort(401);$event=$r->json()->all();$ref=data_get($event,'data.reference');$key=hash('sha256',$raw);if(PaymentEvent::where('event_key',$key)->exists())return response()->json(['ok'=>true]);PaymentEvent::create(['event_key'=>$key,'event_type'=>$event['event']??'unknown','reference'=>$ref,'payload'=>$event,'processed_at'=>now()]);return response()->json(['ok'=>true]);}
}